                    let truncated = self.safe_truncate(&text, 8000);
                    Ok(format!("(FETCHED CONTENT FROM {}):\n\n{}", url, truncated))
                }
                Err(e) => Ok(format!("(FETCH FAILED: {})", e)),
            }
        }
    }

