                format!("Failed to serialize metrics: {}", e)
            ))?
        );

        self.broadcast_agent(
            ctx,
            &format!(
                "📊 Governance: reviewed live metrics (${:.4} / ${:.2})",
                cost, budget
            ),
            "info",
        );

        Ok(metrics_str)
    }
