    async fn fetch_external_context(&self, ctx: &RunContext) -> (String, String) {
        let pending_directives = super::swarm_persistence::get_pending_directives(
            &self.state.resources.pool,
            &ctx.agent_id,
        )
        .await
        .unwrap_or_default();
        let pending_reviews = super::swarm_persistence::get_pending_reviews(
            &self.state.resources.pool,
            &ctx.agent_id,
        )
        .await
        .unwrap_or_default();

        let directives_str = if pending_directives.is_empty() {
            "No active directives. Proceed with mission objectives.".to_string()
        } else {
            pending_directives
                .iter()
                .map(|d| {
                    format!(
                        "- [Directive] From {}: {}",
                        d.source_agent_id, d.instruction
                    )
                })
                .collect::<Vec<_>>()
                .join("\n")
        };

        let reviews_str = if pending_reviews.is_empty() {
            "No peer reviews pending. Maintain standard quality protocols.".to_string()
        } else {
            pending_reviews
                .iter()
                .map(|r| {
                    format!(
                        "- [Review Task] Target: {}. Requirement: {}",
                        r.requester_id, r.content_to_review
                    )
                })
                .collect::<Vec<_>>()
                .join("\n")
        };

        (directives_str, reviews_str)
    }

