            crate::agent::types::RoleAuthorityLevel::Management => "ORCHESTRATOR (Tier 1)",
            crate::agent::types::RoleAuthorityLevel::Specialist => "SPECIALIST (Tier 2)",
            crate::agent::types::RoleAuthorityLevel::Observer => "AUDITOR (Tier 3)",
