                            let mut entries = Vec::new();
                            while let Some(batch_result) = results.next().await {
                                if let Ok(batch) = batch_result {
                                    if let Ok(mut batch_entries) =
                                        Vec::<MemoryEntry>::try_from(&batch)
                                    {
                                        entries.append(&mut batch_entries);
