/// SEC-01: Validates that a URL is either local/private or uses HTTPS.
/// Prevents accidental transmission of API keys over unencrypted channels to external providers.
fn validate_url_security(url: &str) -> Result<(), AppError> {
    let secure_local = url.contains("localhost")
        || url.contains("127.0.0.1")
        || url.contains("host.docker.internal")
        || url.starts_with("http://192.168.")
        || url.starts_with("http://10.");

    let allow_insecure = std::env::var("TADPOLE_ALLOW_LOCAL_HTTP").is_ok();

    if url.starts_with("http://") && !secure_local && !allow_insecure {
        return Err(AppError::BadRequest(
            "Insecure transmission blocked: API keys cannot be sent over HTTP to external providers. Use HTTPS."
                .to_string(),
        ));
    }
    Ok(())
}

enum ProtocolRouter {
    Anthropic,
    Google,
    OpenAI,
    Ollama,
}

impl ProtocolRouter {
    fn from_protocol(protocol: &str) -> Self {
        match protocol {
            "anthropic" => Self::Anthropic,
            "google" | "gemini" => Self::Google,
            "ollama" => Self::Ollama,
            _ => Self::OpenAI, // Default for standard open-compatible endpoints
        }
    }

    fn build_models_url(&self, protocol: &str, base_url: &str, is_sync: bool) -> String {
        match self {
            Self::Anthropic => format!(
                "{}/v1/models",
                if base_url.is_empty() {
                    "https://api.anthropic.com"
                } else {
                    base_url.trim_end_matches('/')
                }
            ),
            Self::Google => {
                let base = if base_url.is_empty() {
                    "https://generativelanguage.googleapis.com".to_string()
                } else {
                    base_url.trim_end_matches('/').to_string()
                };
                if is_sync {
                    format!("{}/v1/models", base)
                } else {
                    let mut b = base;
                    if !b.contains("/v1") && !b.contains("/beta") {
                        b.push_str("/v1");
                    }
                    format!("{}/models", b)
                }
            }
            Self::Ollama => {
                let base = if base_url.is_empty() {
                    get_ollama_host()
                } else {
                    base_url.trim_end_matches('/').to_string()
                };
                let base = if !base.contains("/api") && !base.contains("/v1") {
                    format!("{}/api", base)
                } else {
                    base
                };
                if is_sync && !base.contains("/v1") {
                    format!("{}/tags", base)
                } else {
                    format!("{}/models", base)
                }
            }
            Self::OpenAI => format!(
                "{}/models",
                if base_url.is_empty() {
                    match protocol {
                        "groq" => "https://api.groq.com/openai/v1",
                        _ => "https://api.openai.com/v1",
                    }
                } else {
                    base_url.trim_end_matches('/')
                }
            ),
        }
    }

    fn authenticate_request(
        &self,
        req: reqwest::RequestBuilder,
        api_key: &str,
    ) -> reqwest::RequestBuilder {
        match self {
            Self::Google => req.header("x-goog-api-key", api_key),
            Self::Anthropic => req
                .header("x-api-key", api_key)
                .header("anthropic-version", "2023-06-01"),
            Self::Ollama => {
                if !api_key.is_empty() {
                    req.header("Authorization", format!("Bearer {}", api_key))
                } else {
                    req
                }
            }
            Self::OpenAI => req.header("Authorization", format!("Bearer {}", api_key)),
        }
    }

    fn parse_discovery_response(&self, body: &serde_json::Value, url: &str) -> Vec<String> {
        let mut discovered_ids = Vec::new();
        match self {
            Self::Ollama if url.contains("/tags") => {
                if let Some(models) = body.get("models").and_then(|m| m.as_array()) {
                    for m in models {
                        if let Some(name) = m.get("name").and_then(|n| n.as_str()) {
                            discovered_ids.push(name.to_string());
                        }
                    }
                }
            }
            Self::Google => {
                if let Some(models) = body.get("models").and_then(|m| m.as_array()) {
                    for m in models {
                        if let Some(name) = m.get("name").and_then(|n| n.as_str()) {
                            discovered_ids.push(name.replace("models/", ""));
                        }
                    }
                }
            }
            _ => {
                // OpenAI standard
                if let Some(data) = body.get("data").and_then(|d| d.as_array()) {
                    for m in data {
                        if let Some(id) = m.get("id").and_then(|i| i.as_str()) {
                            discovered_ids.push(id.to_string());
                        }
                    }
                }
            }
        }
        discovered_ids
    }
}

