            .iter()
            .filter_map(|kv| {
                let agent = kv.value();
                let id = &agent.identity.id;

                // Skip root/orchestrator nodes for the specialist directory
                if id == "1" || id == "2" || id == "alpha" || id == "general" {
                    return None;
