    const [sort_key, set_sort_key] = React.useState<'cost' | 'throughput' | 'util' | 'name'>('cost');
    const [sort_dir, set_sort_dir] = React.useState<'asc' | 'desc'>('desc');

    const join_chat = (agent_id: string): void => {
        set_selected_agent_id(agent_id);
        set_scope('agent');
        set_detached(false);
