                        </motion.div>
                        <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 whitespace-nowrap opacity-60">
                            <span className="text-[8px] text-zinc-400 font-mono uppercase">{agent.name}</span>
                        </div>
                    </div>
                );
            })}
