                            id="provider-audio-model"
                            className="w-full bg-[color:var(--color-background)] border border-[color:var(--color-border)] rounded-lg px-3 py-1.5 text-xs text-green-400 focus:outline-none focus:border-green-500 font-mono"
                            placeholder={i18n.t('provider.placeholder_audio_model')}
