                                    <Tooltip content={i18n.t('provider.rpm_tooltip')} position="top">
                                        <Info size={9} className="text-zinc-700 hover:text-green-400 cursor-help transition-colors" />
                                    </Tooltip>
                                </label>
                                <input
                                    id="forge-rpm"
