                            <span className="text-cyan-400">📦</span> {i18n.t('import.title', { type: type.toUpperCase() })}
                        </h3>
                        <p className="text-[10px] text-zinc-500 uppercase font-mono tracking-wider mt-0.5">{i18n.t('import.subtitle')}</p>
                    </div>
                    <button 
