                            <p className="text-[11px] text-emerald-500/70 leading-relaxed font-medium">
                                {i18n.t('import.security_verified_desc')} {/* SSL Secure Verification */}
                            </p>
                        </div>
                    </div>

                    {/* Category Selection (UX: Fitts' Law - Larger Targets) */}
