import { i18n } from '../i18n';

export interface OversightStats {
    pending: number;
    approved: number;
    rejected: number;
}

export interface UseOversightDashboardHook {
    pending: OversightEntry[];
    ledger: LedgerEntry[];
    stats: OversightStats;
    filter: string;
    is_simulated: boolean;
    selected_cluster_id: string;
    is_online: boolean;

