function Detached_Agent_Status({ tab_id }: { tab_id?: string }) {
    const {
        agents_list,
        assigned_agent_ids,
        available_roles,
        clusters,
        toggle_cluster_active,
        update_agent,
    } = useDashboardData();

    return (
