            case 'agent-status':
                return <Detached_Agent_Status tab_id={tab_id || undefined} />;

            case 'agent-config':
                return <Detached_Agent_Config id={id} />;

            case 'tab': {
                const route = get_route_by_path(path || '/dashboard');
                const Component = route.component;
                return (
                    <div className="h-screen bg-[color:var(--color-background)] p-6 flex flex-row gap-6 overflow-hidden">
                        <div className="flex-1 relative overflow-auto custom-scrollbar">
