                .filter(cid => !used_higher_ids.has(cid))
                .map(cid => combined_agents.find(a => a.id === cid))
                .filter(Boolean) as Agent[]
        }));

        return {
            alpha, nexus, chains
        };
    }, [agents_list, clusters]);

